CREATE DATABASE IF NOT EXISTS DEPED_BULIG CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE DEPED_BULIG;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id VARCHAR(30) NOT NULL UNIQUE, role ENUM('admin','teacher','pupil') NOT NULL, name VARCHAR(150) NOT NULL, password_hash VARCHAR(255) NOT NULL, active BOOLEAN NOT NULL DEFAULT 1, avatar_path VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE admins(user_id BIGINT UNSIGNED PRIMARY KEY, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE teachers(user_id BIGINT UNSIGNED PRIMARY KEY, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE grade_levels(id TINYINT UNSIGNED PRIMARY KEY, name VARCHAR(30) NOT NULL);
INSERT INTO grade_levels VALUES (1,'Grade 1'),(2,'Grade 2'),(3,'Grade 3'),(4,'Grade 4'),(5,'Grade 5'),(6,'Grade 6');
CREATE TABLE pupils(user_id BIGINT UNSIGNED PRIMARY KEY, grade_level TINYINT UNSIGNED NOT NULL, section VARCHAR(80) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(grade_level) REFERENCES grade_levels(id));
CREATE TABLE teacher_pupils(teacher_id BIGINT UNSIGNED NOT NULL, pupil_id BIGINT UNSIGNED PRIMARY KEY, FOREIGN KEY(teacher_id) REFERENCES teachers(user_id), FOREIGN KEY(pupil_id) REFERENCES pupils(user_id));
CREATE TABLE id_sequences(kind VARCHAR(20) PRIMARY KEY, next_value BIGINT UNSIGNED NOT NULL);
INSERT INTO id_sequences VALUES ('pupil',20260001),('teacher',2026001);
CREATE TABLE bulig_levels(id INT UNSIGNED PRIMARY KEY, title VARCHAR(150) NOT NULL, published BOOLEAN NOT NULL DEFAULT 0);
INSERT INTO bulig_levels VALUES(1,'Oral Language',1),(2,'Level 2A — Content not installed',0),(3,'Level 2B — Content not installed',0),(4,'Level 3 — Content not installed',0),(5,'Level 4 — Content not installed',0),(6,'Level 5 — Content not installed',0),(7,'Level 6 — Content not installed',0);
CREATE TABLE modules(id INT UNSIGNED PRIMARY KEY, level_id INT UNSIGNED NOT NULL, title VARCHAR(200) NOT NULL, grade_level TINYINT UNSIGNED NULL, FOREIGN KEY(level_id) REFERENCES bulig_levels(id), FOREIGN KEY(grade_level) REFERENCES grade_levels(id));
INSERT INTO modules VALUES(1,1,'Level 1 – Oral Language, First Edition 2025',NULL);
CREATE TABLE lessons(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, module_id INT UNSIGNED NOT NULL, position INT NOT NULL, title VARCHAR(255) NOT NULL, subtitle VARCHAR(255), objectives TEXT NOT NULL, teacher_guide LONGTEXT NOT NULL, source_pages JSON NOT NULL, image_path VARCHAR(255), published BOOLEAN NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(module_id,position), FOREIGN KEY(module_id) REFERENCES modules(id));
CREATE TABLE assessments(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, lesson_id INT UNSIGNED NOT NULL, kind ENUM('pre','post') NOT NULL, title VARCHAR(255) NOT NULL, rubric TEXT NOT NULL, source_page INT NOT NULL, source_note TEXT, UNIQUE(lesson_id,kind), FOREIGN KEY(lesson_id) REFERENCES lessons(id));
CREATE TABLE activities(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, lesson_id INT UNSIGNED NOT NULL, assessment_id INT UNSIGNED NULL, phase ENUM('pre','learn','post') NOT NULL, position INT NOT NULL, title VARCHAR(255) NOT NULL, type ENUM('open','sentence','reading','physical','group','drawing','choice','exact','reference') NOT NULL, instructions TEXT NOT NULL, prompt TEXT NOT NULL, image_path VARCHAR(255), image_paths JSON, narration TEXT NOT NULL, expected_text TEXT, xp_reward INT UNSIGNED NOT NULL DEFAULT 10, source_page INT NOT NULL, source_excerpt TEXT NOT NULL, published BOOLEAN NOT NULL DEFAULT 1, revision INT UNSIGNED NOT NULL DEFAULT 1, UNIQUE(lesson_id,phase,position), FOREIGN KEY(lesson_id) REFERENCES lessons(id), FOREIGN KEY(assessment_id) REFERENCES assessments(id));
CREATE TABLE questions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, activity_id INT UNSIGNED NOT NULL UNIQUE, content TEXT NOT NULL, grading ENUM('teacher','exact') NOT NULL DEFAULT 'teacher', FOREIGN KEY(activity_id) REFERENCES activities(id));
CREATE TABLE answers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, question_id BIGINT UNSIGNED NOT NULL, content TEXT NOT NULL, correct BOOLEAN NOT NULL DEFAULT 0, FOREIGN KEY(question_id) REFERENCES questions(id));
CREATE TABLE assessment_questions(assessment_id INT UNSIGNED NOT NULL, question_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(assessment_id,question_id), FOREIGN KEY(assessment_id) REFERENCES assessments(id), FOREIGN KEY(question_id) REFERENCES questions(id));
CREATE TABLE pupil_level_assignments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, pupil_id BIGINT UNSIGNED NOT NULL UNIQUE, level_id INT UNSIGNED NOT NULL, assigned_by BIGINT UNSIGNED NOT NULL, assigned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(pupil_id) REFERENCES pupils(user_id), FOREIGN KEY(level_id) REFERENCES bulig_levels(id), FOREIGN KEY(assigned_by) REFERENCES teachers(user_id));
CREATE TABLE pupil_progress(pupil_id BIGINT UNSIGNED NOT NULL, lesson_id INT UNSIGNED NOT NULL, last_activity_id INT UNSIGNED, completed_at DATETIME NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(pupil_id,lesson_id), FOREIGN KEY(pupil_id) REFERENCES pupils(user_id), FOREIGN KEY(lesson_id) REFERENCES lessons(id), FOREIGN KEY(last_activity_id) REFERENCES activities(id));
CREATE TABLE activity_completion(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, pupil_id BIGINT UNSIGNED NOT NULL, activity_id INT UNSIGNED NOT NULL, response TEXT NOT NULL, drawing LONGTEXT NULL, transcript TEXT NULL, prompt_snapshot TEXT NOT NULL, activity_revision INT UNSIGNED NOT NULL, status ENUM('submitted','approved','retry') NOT NULL DEFAULT 'submitted', score DECIMAL(5,2) NULL, max_score DECIMAL(5,2) NULL, feedback TEXT NULL, reviewed_by BIGINT UNSIGNED NULL, submitted_at DATETIME NOT NULL, reviewed_at DATETIME NULL, UNIQUE(pupil_id,activity_id), INDEX(status), FOREIGN KEY(pupil_id) REFERENCES pupils(user_id), FOREIGN KEY(activity_id) REFERENCES activities(id), FOREIGN KEY(reviewed_by) REFERENCES users(id));
CREATE TABLE response_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, completion_id BIGINT UNSIGNED NOT NULL, response TEXT NOT NULL, status VARCHAR(20) NOT NULL, actor_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(completion_id) REFERENCES activity_completion(id), FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE activity_drafts(pupil_id BIGINT UNSIGNED NOT NULL, activity_id INT UNSIGNED NOT NULL, response TEXT NOT NULL, drawing LONGTEXT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(pupil_id,activity_id), FOREIGN KEY(pupil_id) REFERENCES pupils(user_id), FOREIGN KEY(activity_id) REFERENCES activities(id));
CREATE TABLE assessment_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, pupil_id BIGINT UNSIGNED NOT NULL, assessment_id INT UNSIGNED NOT NULL, status ENUM('in_progress','submitted','reviewed') NOT NULL, score DECIMAL(8,2) NULL, max_score DECIMAL(8,2) NULL, completed_at DATETIME NULL, UNIQUE(pupil_id,assessment_id), FOREIGN KEY(pupil_id) REFERENCES pupils(user_id), FOREIGN KEY(assessment_id) REFERENCES assessments(id));
CREATE TABLE pupil_xp(pupil_id BIGINT UNSIGNED PRIMARY KEY, total INT UNSIGNED NOT NULL DEFAULT 0, FOREIGN KEY(pupil_id) REFERENCES pupils(user_id));
CREATE TABLE xp_transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, pupil_id BIGINT UNSIGNED NOT NULL, activity_id INT UNSIGNED NOT NULL, amount INT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(pupil_id,activity_id), FOREIGN KEY(pupil_id) REFERENCES pupils(user_id), FOREIGN KEY(activity_id) REFERENCES activities(id));
CREATE TABLE learning_days(pupil_id BIGINT UNSIGNED NOT NULL, day DATE NOT NULL, PRIMARY KEY(pupil_id,day), FOREIGN KEY(pupil_id) REFERENCES pupils(user_id));
CREATE TABLE pupil_streaks(pupil_id BIGINT UNSIGNED PRIMARY KEY, current_streak INT UNSIGNED NOT NULL DEFAULT 0, longest_streak INT UNSIGNED NOT NULL DEFAULT 0, last_activity_date DATE NULL, FOREIGN KEY(pupil_id) REFERENCES pupils(user_id));
CREATE TABLE badges(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(100) NOT NULL, description VARCHAR(255) NOT NULL, rule_type ENUM('activity','lesson','xp','streak','level','reading','perfect') NOT NULL, threshold_value INT UNSIGNED NOT NULL, active BOOLEAN NOT NULL DEFAULT 1);
INSERT INTO badges(title,description,rule_type,threshold_value) VALUES('First step','Complete your first activity','activity',1),('Lesson explorer','Complete your first lesson','lesson',1),('Bright voice','Complete a reading activity','reading',1),('100 XP club','Earn 100 XP','xp',100),('Seven days of learning','Learn on seven consecutive days','streak',7),('Thirty-day learner','Learn on thirty consecutive days','streak',30),('Oral Language champion','Complete all 12 lessons','level',12),('Perfect assessment','Earn full marks on a reviewed assessment','perfect',1);
CREATE TABLE pupil_badges(pupil_id BIGINT UNSIGNED NOT NULL, badge_id INT UNSIGNED NOT NULL, earned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(pupil_id,badge_id), FOREIGN KEY(pupil_id) REFERENCES pupils(user_id), FOREIGN KEY(badge_id) REFERENCES badges(id));
CREATE TABLE rewards(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(100) NOT NULL, required_xp INT UNSIGNED NOT NULL, active BOOLEAN NOT NULL DEFAULT 1);
INSERT INTO rewards(title,required_xp) VALUES('Reading spark',100),('Learning star',500),('Golden voice',1000);
CREATE TABLE pupil_rewards(pupil_id BIGINT UNSIGNED NOT NULL, reward_id INT UNSIGNED NOT NULL, earned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(pupil_id,reward_id), FOREIGN KEY(pupil_id) REFERENCES pupils(user_id), FOREIGN KEY(reward_id) REFERENCES rewards(id));
CREATE TABLE reading_assessments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, pupil_id BIGINT UNSIGNED NOT NULL, activity_id INT UNSIGNED NOT NULL, transcript TEXT NOT NULL, expected_text TEXT NOT NULL, word_match_percent DECIMAL(5,2) NOT NULL, detail JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(pupil_id) REFERENCES pupils(user_id), FOREIGN KEY(activity_id) REFERENCES activities(id));
CREATE TABLE source_pages(page_number INT UNSIGNED PRIMARY KEY, text_content LONGTEXT NOT NULL, image_path VARCHAR(255) NOT NULL, images JSON NOT NULL);
CREATE TABLE content_issues(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, description TEXT NOT NULL, resolution TEXT, acknowledged_by BIGINT UNSIGNED NULL, acknowledged_at DATETIME NULL, FOREIGN KEY(acknowledged_by) REFERENCES admins(user_id));
CREATE TABLE settings(setting_key VARCHAR(80) PRIMARY KEY, setting_value TEXT NOT NULL);
INSERT INTO settings VALUES('site_name','BULIG'),('timezone','Asia/Manila');
CREATE TABLE login_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, identifier_hash CHAR(64) NOT NULL, attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(identifier_hash,attempted_at));
CREATE TABLE audit_log(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, details TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_id) REFERENCES users(id));
ALTER TABLE assessments ADD rubric_criteria JSON NULL;
ALTER TABLE assessment_attempts ADD rubric_scores JSON NULL, ADD feedback TEXT NULL, ADD reviewed_by BIGINT UNSIGNED NULL, ADD FOREIGN KEY(reviewed_by) REFERENCES teachers(user_id);
